#!/bin/sh
#
# Сборщик пакета luci-app-sing-box-service-check в формате APKv3 для OpenWrt 25.12 и новее.
#
# APKv3 - бинарный формат (ADB), собрать его может только apk-tools v3, поэтому
# скрипт зовёт `apk mkpkg`. Запускать там, где apk есть:
#
#   на самом роутере с OpenWrt 25.12:   sh make-apk.sh
#   в контейнере Alpine:                docker run --rm -v "$PWD:/w" -w /w alpine:edge sh -c "apk add apk-tools && sh make-apk.sh"
#
# Готовый пакет ставится так:
#   apk add --allow-untrusted ./luci-app-sing-box-service-check-1.14.0-r1.apk
#
# Можно сразу подписать, тогда --allow-untrusted не нужен:
#   sh make-apk.sh --sign-key mykey.pem
#
# Ключ - обычный EC в PEM. Создать пару:
#   openssl ecparam -name prime256v1 -genkey -noout -out mykey.pem
#   openssl ec -in mykey.pem -pubout -out mykey.pub.pem
# Публичный ключ раскладывается на роутеры в /etc/apk/keys/.
#
# Пакет архитектурно-независим (arch: noarch).
#

set -e

PACKAGE="luci-app-sing-box-service-check"
VERSION="1.14.0-r1"
ARCH="noarch"
OUTPUT="${PACKAGE}-${VERSION}.apk"
SIGN_KEY=""

while [ $# -gt 0 ]; do
    case "$1" in
        --sign-key) SIGN_KEY="$2"; shift 2 ;;
        --output|-o) OUTPUT="$2"; shift 2 ;;
        -h|--help)
            echo "Usage: sh make-apk.sh [--sign-key KEYFILE] [--output FILE]"
            echo
            echo "  --sign-key KEYFILE  подписать пакет приватным ключом (EC/RSA в PEM)"
            echo "  --output FILE       имя итогового файла"
            exit 0
            ;;
        *) echo "Неизвестный аргумент: $1" >&2; exit 1 ;;
    esac
done

log() {
    printf '\033[0;36m[make-apk]\033[0m %s\n' "$1"
}

fail() {
    printf '\033[0;31m[make-apk]\033[0m %s\n' "$1" >&2
    exit 1
}

command -v apk >/dev/null 2>&1 || fail "Не найден apk. Нужен apk-tools v3: запустите на роутере с OpenWrt 25.12 или в контейнере Alpine."

# Проверяем по выводу, а не по коду возврата: apk на --help выходит с кодом 1.
if ! apk mkpkg --help 2>&1 | grep -q "mkpkg"; then
    fail "У этой сборки apk нет команды mkpkg. Нужен полноценный apk-tools v3 (например, пакет apk-tools в Alpine)."
fi

command -v base64 >/dev/null 2>&1 || fail "Не найдена утилита base64."
command -v tar >/dev/null 2>&1 || fail "Не найдена утилита tar."

WORK="$(mktemp -d /tmp/make-apk.XXXXXX)"
cleanup() {
    rm -rf "$WORK"
}
trap cleanup EXIT INT TERM

ROOTFS="$WORK/rootfs"
SCRIPTS="$WORK/scripts"
mkdir -p "$ROOTFS" "$SCRIPTS"

log "Разворачиваю файлы пакета"
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xzf - -C "$ROOTFS"

[ -f "$ROOTFS/usr/lib/sing-box-service-check/probe.uc" ] || fail "В архиве нет движка проверки."

chmod 0755 "$ROOTFS/usr/bin/sing-box-service-check"

cat > "$SCRIPTS/post-install" <<'POST_INSTALL_EOF'
#!/bin/sh
[ -n "$IPKG_INSTROOT" ] && exit 0

# Кеш диспетчера LuCI держит список пунктов меню - без сброса новая страница
# не появится до перезагрузки.
rm -rf /tmp/luci-modulecache 2>/dev/null
rm -f /tmp/luci-indexcache* 2>/dev/null
rm -f /usr/share/luci/menu.d/luci-app-forkop-servicecheck.json /usr/share/rpcd/acl.d/luci-app-forkop-servicecheck.json 2>/dev/null
rm -f /www/luci-static/resources/view/sing-box-service-check/servicecheck-v1150.js 2>/dev/null
rm -f /www/luci-static/resources/view/sing-box-service-check/servicecheck-v1151.js 2>/dev/null
rm -f /www/luci-static/resources/view/sing-box-service-check/servicecheck-v1142.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1141.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1140.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1130.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1125.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1124.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1123.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1122.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1121.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1120.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1112.js 2>/dev/null
rm -f /www/luci-static/resources/view/forkop/servicecheck-v1110.js 2>/dev/null

[ -s /www/luci-static/resources/view/sing-box-service-check/servicecheck-v1140.js ] || exit 1
/usr/lib/sing-box-service-check/migrate.sh || exit 1
cp -f /usr/bin/sing-box-service-check /usr/bin/forkop-servicecheck || exit 1
chmod 0755 /usr/bin/forkop-servicecheck

# rpcd читает acl.d только при старте.
[ -x /etc/init.d/rpcd ] && /etc/init.d/rpcd restart >/dev/null 2>&1

exit 0

POST_INSTALL_EOF

cat > "$SCRIPTS/pre-deinstall" <<'PRE_DEINSTALL_EOF'
#!/bin/sh
[ -n "$IPKG_INSTROOT" ] && exit 0

# Убираем временный network namespace, если проверка оборвалась на полпути.
[ -x /usr/bin/sing-box-service-check ] && /usr/bin/sing-box-service-check netns_teardown >/dev/null 2>&1
rm -rf /var/run/sing-box-service-check 2>/dev/null

exit 0

PRE_DEINSTALL_EOF

chmod 0755 "$SCRIPTS/post-install" "$SCRIPTS/pre-deinstall"

if [ -n "$SIGN_KEY" ]; then
    [ -f "$SIGN_KEY" ] || fail "Файл ключа не найден: $SIGN_KEY"
fi

# Флаги ровно те же, что использует сборочная система OpenWrt (include/package-pack.mk).
build_package() {
    SOURCE_DATE_EPOCH=0 apk mkpkg \
        "$@" \
        --info "name:$PACKAGE" \
        --info "version:$VERSION" \
        --info "description:Sing-box Service Check для Tachyon, HomeProxy, Forkop и оригинального Podkop. Добавляет в LuCI страницу с кнопкой проверки: Telegram, YouTube, Instagram и другие сервисы проверяются тем же путём, которым идёт трафик клиента сети - через dnsmasq, sing-box и tproxy. Показывает DNS, TCP, TLS, код ответа и выбранный outbound." \
        --info "arch:$ARCH" \
        --info "license:MIT" \
        --info "origin:$PACKAGE" \
        --info "url:https://github.com/Hellington-Rey/sing-box-service-check" \
        --info "maintainer:Sing-box Service Check" \
        --info "depends:luci-base ucode" \
        --info "provides:luci-app-forkop-servicecheck=$VERSION" \
        --info "replaces:luci-app-forkop-servicecheck" \
        --script "post-install:$SCRIPTS/post-install" \
        --script "pre-deinstall:$SCRIPTS/pre-deinstall" \
        --files "$ROOTFS" \
        --output "$OUTPUT"
}

SIGNED=0

if [ -n "$SIGN_KEY" ]; then
    log "Собираю $OUTPUT с подписью"
    # --sign-key есть в опциях генерации mkpkg (проверено на apk-tools 3.0.6).
    # На случай сборок, где его нет, оставлен запасной путь через adbsign.
    if build_package --sign-key "$SIGN_KEY" 2>/tmp/.mkpkg-err; then
        SIGNED=1
    else
        log "mkpkg не принял --sign-key ($(head -1 /tmp/.mkpkg-err)), подпишу отдельно через adbsign"
        build_package || fail "apk mkpkg не смог собрать пакет: $(head -3 /tmp/.mkpkg-err)"
        apk adbsign --sign-key "$SIGN_KEY" "$OUTPUT" || fail "apk adbsign не смог подписать пакет."
        SIGNED=1
    fi
    rm -f /tmp/.mkpkg-err
else
    log "Собираю $OUTPUT без подписи"
    build_package
fi

[ -f "$OUTPUT" ] || fail "apk mkpkg не создал файл."

log "Готово: $OUTPUT ($(wc -c < "$OUTPUT") байт)"

if [ "$SIGNED" = "1" ]; then
    if apk verify "$OUTPUT" >/dev/null 2>&1; then
        log "Подпись проверена: apk verify доволен"
    else
        log "Внимание: apk verify не признал подпись - публичный ключ ещё не в /etc/apk/keys/?"
    fi
    cat <<EOF

Установка:
  apk add ./$OUTPUT

Публичный ключ должен лежать в /etc/apk/keys/ на целевом роутере:
  openssl ec -in <ваш ключ>.pem -pubout -out /etc/apk/keys/sing-box-service-check.pem

EOF
else
    cat <<EOF

Установка:
  apk add --allow-untrusted ./$OUTPUT

Пакет не подписан, поэтому нужен --allow-untrusted.
Подписать сразу при сборке: sh make-apk.sh --sign-key ваш-ключ.pem

EOF
fi

exit 0

